  const bookingId=createHash('sha256').update(`${lateUpgradeRecord.id}:${invalidEvidence}`).digest('hex'),caseId=`live_invalid_return_${bookingId}`,paymentIntentId=`pi_${bookingId}`;
  const source={...(await db.collection('liveEventBookings').doc(lateUpgradeRecord.id).get()).data(),id:bookingId,status:'payment_review_required',refundCaseId:caseId,providerPaymentIntentId:paymentIntentId,providerChargeId:`ch_${bookingId}`,stripeCheckoutSessionId:`cs_${bookingId}`};
  const evidence=capturedBooking(source,source.stripeCheckoutSessionId);
  await db.collection('liveEventBookings').doc(bookingId).set(source);
  await db.collection('refundCases').doc(caseId).set({...lateCaseSnap.docs[0].data(),id:caseId,paymentId:bookingId,providerPaymentIntentId:paymentIntentId,providerChargeId:source.providerChargeId,status:'financial_hold'});
  await db.collection('paymentProviderLocks').doc(createHash('sha256').update(`live_event:${paymentIntentId}`).digest('hex')).set({bookingId});
  if(invalidEvidence==='wrong_intent')evidence.intent.id='pi_unrelated';
  if(invalidEvidence==='disputed')evidence.intent.latest_charge.disputed=true;
  if(invalidEvidence==='unsupported_method')evidence.intent.latest_charge.payment_method_details.type='us_bank_account';
  if(invalidEvidence==='unconfirmed_capture')evidence.intent.latest_charge.captured=false;
  let unsafeRefundCalls=0;
  const unsafeProvider={paymentIntents:{retrieve:async()=>{if(invalidEvidence==='missing_provider')throw new Error('offline provider failure');return evidence.intent;}},checkout:{sessions:{retrieve:async()=>evidence.session}},refunds:{create:async()=>{unsafeRefundCalls++;throw new Error('must not execute');}}};
  const outcome=await returnLiveEventUnfulfilledPayment(db,unsafeProvider,{...returnInput,caseId});
  equal(outcome.status,'financial_hold',`${invalidEvidence} stays in auditable review`);
